Retrieve my current list of match_candidates within 15 miles that have a compatibility score above 80 and include reason_codes indicating both dog compatibility and shared outdoors lifestyle, and return the top 10 sorted by score descending.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Task requires returning match_candidates with specific filters
    # Check if final_answer exists and is not empty
    if not final_answer or len(final_answer.strip()) == 0:
        return {"result": "others"}

    # Query the database for the expected results
    query = """
        SELECT candidate_user_id, distance_miles, compatibility_score, 
               reason_dog_compatibility, reason_shared_outdoors_lifestyle
        FROM match_candidates
        WHERE user_id = 1
          AND distance_miles <= 15
          AND compatibility_score > 80
          AND reason_dog_compatibility = 1
          AND reason_shared_outdoors_lifestyle = 1
        ORDER BY compatibility_score DESC
        LIMIT 10
    """

    expected_results = safe_query(final_db_path, query)

    if not expected_results:
        return {"result": "others"}

    # Extract candidate user IDs from expected results
    expected_candidate_ids = [row[0] for row in expected_results]
    expected_scores = [row[2] for row in expected_results]

    # Verify we have the expected number of candidates (should be 5 based on initial data)
    # Candidates that meet criteria: 2(95.0, 5mi), 3(92.5, 8mi), 4821(91.0, 2mi), 5(88.0, 10mi), 7(85.0, 12mi), 8(83.0, 14.5mi)
    if len(expected_results) == 0:
        return {"result": "others"}

    # Check if final_answer contains all expected candidate IDs
    found_count = 0
    for candidate_id in expected_candidate_ids:
        # Look for the candidate ID in various possible formats
        patterns = [
            rf"\b{candidate_id}\b",  # Direct ID match
            rf"candidate[_\s]*user[_\s]*id[^\d]*{candidate_id}\b",  # candidate_user_id: X
            rf"user[_\s]*id[^\d]*{candidate_id}\b",  # user_id: X
            rf"id[^\d]*{candidate_id}\b"  # id: X
        ]

        for pattern in patterns:
            if re.search(pattern, final_answer, re.IGNORECASE):
                found_count += 1
                break

    # Verify all expected candidates are mentioned
    if found_count < len(expected_candidate_ids):
        return {"result": "others"}

    # Check if scores are mentioned and in descending order
    score_matches = re.findall(r"\b(\d{2,3}\.\d+|\d{2,3})\b", final_answer)
    if score_matches:
        extracted_scores = []
        for score_str in score_matches:
            try:
                score = float(score_str)
                if 80 < score <= 100:  # Valid score range
                    extracted_scores.append(score)
            except ValueError:
                continue

        # If we found scores, verify they are in descending order
        if len(extracted_scores) >= 2:
            is_descending = all(extracted_scores[i] >= extracted_scores[i+1] for i in range(len(extracted_scores)-1))
            if not is_descending:
                return {"result": "others"}

    # Verify the answer indicates filtering by distance, score, and reason codes
    has_distance_ref = bool(re.search(r"(15\s*miles?|within\s*15|distance|miles?\s*<=?\s*15)", final_answer, re.IGNORECASE))
    has_score_ref = bool(re.search(r"(80|score|compatibility|above\s*80)", final_answer, re.IGNORECASE))
    has_dog_ref = bool(re.search(r"(dog|reason[_\s]*dog|dog[_\s]*compatibility)", final_answer, re.IGNORECASE))
    has_outdoors_ref = bool(re.search(r"(outdoor|lifestyle|shared[_\s]*outdoor)", final_answer, re.IGNORECASE))

    # At least some of the filter criteria should be mentioned or implied
    criteria_mentioned = sum([has_distance_ref, has_score_ref, has_dog_ref, has_outdoors_ref])

    if criteria_mentioned < 2:
        return {"result": "others"}

    # Check if "top 10" or similar limit is mentioned or implied
